import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/dungeon/configuration.md","filePath":"en/modules/dungeon/configuration.md","lastUpdated":0}`),a={name:`en/modules/dungeon/configuration.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>EmakiDungeon ships three configuration files: the global <code>plugins/EmakiDungeon/config.yml</code>, the per-dungeon <code>plugins/EmakiDungeon/world/&lt;dungeonId&gt;/config.yml</code>, and the reward box GUI <code>plugins/EmakiDungeon/gui/rewardbox.yml</code>. After you edit them, run <code>/edg admin reload</code> (this command is run by a player with <code>emakidungeon.admin</code>); running instances are unaffected, only newly created instances pick the changes up</p><p>The top-level <code>version</code> and <code>language</code> fields are maintained by the resource sync process — do not edit them by hand. Per-dungeon configs have <strong>no schema compatibility layer</strong> and are validated strictly at load time. The &quot;Range&quot; column below marks keys with source-level validation; keys showing <code>—</code> are not range-checked by the code, and invalid values are handled in one of two ways:</p><ul><li><strong>Load error</strong> (the dungeon is skipped, console reports an invalid dungeon configuration): <code>pool.max-worlds</code>, <code>enter.prepare-window-seconds</code>, <code>enter.wait-timeout-seconds</code>, <code>enter.wait-channel</code>, the <code>limits.daily.time-window</code> format, and <code>days</code>/<code>weeks</code> entries under <code>limits</code></li><li><strong>Silent fallback</strong>: the plugin drops invalid entries, clamps them to a boundary, or replaces them with the default (see each row)</li></ul><h2 id="global-config-yml" tabindex="-1">Global <code>config.yml</code> <a class="header-anchor" href="#global-config-yml" aria-label="Permalink to “Global config.yml”">​</a></h2><h3 id="debug" tabindex="-1"><code>debug</code> <a class="header-anchor" href="#debug" aria-label="Permalink to “debug”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>debug.enabled</code></td><td>boolean</td><td><code>false</code></td><td><code>true</code> / <code>false</code></td><td>Debug anchor logging; prints detailed instance, party, and limit events to console</td></tr><tr><td><code>debug.retention-days</code></td><td>int</td><td><code>30</code></td><td><code>—</code></td><td>How many days audit and debug logs are kept before cleanup</td></tr></tbody></table><h3 id="limit-and-commands" tabindex="-1"><code>limit</code> and <code>commands</code> <a class="header-anchor" href="#limit-and-commands" aria-label="Permalink to “limit and commands”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>limit.max-instances</code></td><td>int</td><td><code>20</code></td><td><code>—</code></td><td>Global cap on concurrent instance worlds (including spare worlds); new challenges are refused once reached</td></tr><tr><td><code>commands.mode</code></td><td>string</td><td><code>blacklist</code></td><td><code>blacklist</code> / <code>whitelist</code></td><td>Command filter mode: blacklist refuses only what <code>commands.rules</code> lists, whitelist allows only what it lists</td></tr><tr><td><code>commands.rules</code></td><td>list&lt;string&gt;</td><td><code>[]</code></td><td>See description</td><td>Rule = command root + argument pattern, for example <code>&quot;/tpa player&quot;</code>; write the placeholder <code>player</code> where a player name goes</td></tr><tr><td><code>escape.blacklist</code></td><td>list&lt;string&gt;</td><td><code>[]</code></td><td>Supports <code>*</code> wildcards</td><td>Escape-command blacklist (for example <code>&quot;/tp *&quot;</code>, <code>&quot;/back&quot;</code>); highest priority, <strong>no allow-rule can exempt it</strong></td></tr></tbody></table><h3 id="party-and-isolation" tabindex="-1"><code>party</code> and <code>isolation</code> <a class="header-anchor" href="#party-and-isolation" aria-label="Permalink to “party and isolation”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>party.max-size</code></td><td>int</td><td><code>4</code></td><td><code>—</code></td><td>Party member cap</td></tr><tr><td><code>party.invite-mode</code></td><td>string</td><td><code>public</code></td><td><code>public</code> / <code>apply</code> / <code>invite</code></td><td>What happens when a player without a party asks to join: <code>public</code> joins directly, <code>apply</code> files an application for approval, <code>invite</code> only lets invited players in (other values behave like <code>invite</code>)</td></tr><tr><td><code>isolation.global-chat-default</code></td><td>boolean</td><td><code>false</code></td><td><code>true</code> / <code>false</code></td><td>Default global listening for new players; each player can switch with <code>/edg globalchat</code> at any time</td></tr></tbody></table><h3 id="general-and-rewardbox" tabindex="-1"><code>general</code> and <code>rewardbox</code> <a class="header-anchor" href="#general-and-rewardbox" aria-label="Permalink to “general and rewardbox”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>general.timezone</code></td><td>string</td><td><code>&quot;&quot;</code></td><td>Empty or a timezone id</td><td>Timezone for entry-limit bucketing; empty uses the server timezone</td></tr><tr><td><code>rewardbox.enabled</code></td><td>boolean</td><td><code>true</code></td><td><code>true</code> / <code>false</code></td><td>Reward box master switch; when off, dungeon payouts go straight to the inventory, falling to the ground as drops when it is full</td></tr></tbody></table><h3 id="script-graaljs-host" tabindex="-1"><code>script</code> GraalJS host <a class="header-anchor" href="#script-graaljs-host" aria-label="Permalink to “script GraalJS host”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>script.enabled</code></td><td>boolean</td><td><code>true</code></td><td><code>true</code> / <code>false</code></td><td>Load <code>scripts/&lt;dungeonId&gt;.js</code> with every instance; turning it off disables scripting entirely</td></tr><tr><td><code>script.timeout-ms</code></td><td>int</td><td><code>5000</code></td><td><code>—</code></td><td>Timeout for a single script handler (milliseconds); on timeout the script is disabled and the instance continues</td></tr><tr><td><code>script.fail-on-error</code></td><td>boolean</td><td><code>false</code></td><td><code>true</code> / <code>false</code></td><td>Whether a script failure fails the run; <code>false</code> only disables the script and keeps everything else running</td></tr></tbody></table><h3 id="monitor" tabindex="-1"><code>monitor</code> <a class="header-anchor" href="#monitor" aria-label="Permalink to “monitor”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>monitor.mspt-p95-ms</code></td><td>int</td><td><code>55</code></td><td><code>&gt; 0</code>, or <code>&lt;= 0</code> to disable</td><td>Console alert plus audit log entry when the steady-state MSPT P95 exceeds the value</td></tr><tr><td><code>monitor.mspt-p95-enter-ms</code></td><td>int</td><td><code>200</code></td><td><code>&gt; 0</code>, or <code>&lt;= 0</code> to disable</td><td>MSPT P95 threshold for the enter/prepare phase: within 65 seconds after an enter-flow marker (world acquisition, wait, or entry completion) this value is judged instead, alerting and auditing the same way; all other times it falls back to <code>monitor.mspt-p95-ms</code></td></tr><tr><td><code>monitor.memory-slope-mb-per-min</code></td><td>int</td><td><code>64</code></td><td><code>&gt; 0</code>, or <code>&lt;= 0</code> to disable</td><td>Heap slope (MB/minute) alert threshold</td></tr><tr><td><code>monitor.queue-backlog-seconds</code></td><td>int</td><td><code>5</code></td><td><code>&gt; 0</code>, or <code>&lt;= 0</code> to disable</td><td>Sustained write-queue backlog (seconds) alert threshold</td></tr></tbody></table><h3 id="storage-folia-action" tabindex="-1"><code>storage</code> / <code>folia</code> / <code>action</code> <a class="header-anchor" href="#storage-folia-action" aria-label="Permalink to “storage / folia / action”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>storage.bstats</code></td><td>string</td><td><code>disabled</code></td><td><code>disabled</code> only for now</td><td>bStats is not wired up this phase; it will be integrated through CoreLib once the interface lands</td></tr><tr><td><code>folia.held-worlds-max</code></td><td>int</td><td><code>10</code></td><td><code>—</code></td><td>Global cap on suspended worlds on Folia; at capacity new challenges are refused as full and the state resets on restart</td></tr><tr><td><code>action.&lt;segmentId&gt;</code></td><td>map</td><td><code>{}</code></td><td>Action pipeline lines</td><td>Dungeon lifecycle actions; the segment id is the key and the value is a CoreLib action pipeline</td></tr></tbody></table><p>The <code>action</code> section supports 11 segment ids: <code>dungeon_enter</code>, <code>dungeon_exit</code>, <code>dungeon_room_clear</code>, <code>dungeon_gate_open</code>, <code>dungeon_wave_start</code>, <code>dungeon_score</code>, <code>dungeon_complete</code>, <code>dungeon_fail</code>, <code>dungeon_reward</code>, <code>dungeon_ending</code>, <code>dungeon_destroy</code>. You write them with the same syntax as the <a href="./../corelib/actions.html">CoreLib actions</a>, for example:</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  dungeon_enter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | send_message text=&quot;&lt;green&gt;进入副本&lt;/green&gt;&quot;&#39;</span></span></code></pre></div><h2 id="per-dungeon-world-dungeonid-config-yml" tabindex="-1">Per-dungeon <code>world/&lt;dungeonId&gt;/config.yml</code> <a class="header-anchor" href="#per-dungeon-world-dungeonid-config-yml" aria-label="Permalink to “Per-dungeon world/&lt;dungeonId&gt;/config.yml”">​</a></h2><p>When this file is missing, the plugin generates it from the bundled template at startup or reload; existing files are never overwritten</p><h3 id="metadata-and-entry" tabindex="-1">Metadata and entry <a class="header-anchor" href="#metadata-and-entry" aria-label="Permalink to “Metadata and entry”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>display-name</code></td><td>string</td><td><code>示例副本</code></td><td>Any text</td><td>Display name shown in lists and messages (bundled template default)</td></tr><tr><td><code>description</code></td><td>string</td><td><code>一份用于演示的线性副本配置</code></td><td>Any text</td><td>Dungeon description (bundled template default)</td></tr><tr><td><code>difficulty-group</code></td><td>string</td><td><code>default</code></td><td>Any identifier</td><td>Difficulty group identifier</td></tr><tr><td><code>enter.timeout-seconds</code></td><td>int</td><td><code>1800</code></td><td><code>—</code></td><td>Per-run time limit (seconds); when it expires the run is failed: <code>DungeonFailEvent</code> (TIMEOUT) fires and a <strong>failure settlement runs</strong> (audit <code>[settle]</code> records <code>event=fail</code>, <code>reason=timeout</code> and <code>duration_ms</code>; settlement commands and drops still execute), players are sent back to their pre-entry position, and the instance is destroyed as <code>fail:timeout</code>; <code>DungeonCompleteEvent</code> is not fired and the leaderboard is not updated</td></tr><tr><td><code>enter.prepare-window-seconds</code></td><td>int</td><td><code>10</code></td><td><code>&gt;= 1</code></td><td>Ready-confirmation window (seconds); missing the window cancels the challenge; below 1 the dungeon fails to load</td></tr><tr><td><code>enter.wait-channel</code></td><td>string</td><td><code>bossbar</code></td><td><code>bossbar</code> / <code>scoreboard</code> / <code>chat</code></td><td>Progress channel for the world preparation wait; <strong>any other value fails dungeon loading</strong></td></tr><tr><td><code>enter.wait-timeout-seconds</code></td><td>int</td><td><code>60</code></td><td><code>&gt;= 1</code></td><td>Maximum world preparation wait (seconds) before auto-cancel; below 1 the dungeon fails to load</td></tr><tr><td><code>pool.max-worlds</code></td><td>int</td><td><code>5</code></td><td><code>&gt;= 1</code></td><td>Instance world cap for this dungeon (including spares); at capacity players are told to retry later; below 1 the dungeon fails to load</td></tr><tr><td><code>pool.warm-reserves</code></td><td>int</td><td><code>2</code></td><td><code>&gt;= 1</code> (lower values clamp to 1)</td><td>Hot spare count = active instances + this value (never above <code>pool.max-worlds</code>); 2–3 is recommended so clone/mount finishes before the next entry and spare creation never overlaps the player&#39;s entry spike; defaults to 2 when absent</td></tr></tbody></table><h3 id="limits-entry-limits" tabindex="-1"><code>limits</code> entry limits <a class="header-anchor" href="#limits-entry-limits" aria-label="Permalink to “limits entry limits”">​</a></h3><p>The evaluation order is fixed as <strong>month &gt; week &gt; day</strong>: if any tier is unsatisfied or exhausted, entry is refused and lower tiers are not evaluated. <code>count: 0</code> means unlimited for that tier, and negative values are treated as <code>0</code></p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>limits.daily.count</code></td><td>int</td><td><code>1</code></td><td><code>&gt;= 0</code></td><td>Entries per day; <code>0</code> is unlimited</td></tr><tr><td><code>limits.daily.time-window</code></td><td>string</td><td><code>&quot;&quot;</code></td><td><code>&quot;HH:mm-HH:mm&quot;</code> or empty</td><td>Daily challenge window; may cross midnight (for example <code>&quot;23:00-01:00&quot;</code>); a malformed value fails dungeon loading</td></tr><tr><td><code>limits.weekly.count</code></td><td>int</td><td><code>0</code></td><td><code>&gt;= 0</code></td><td>Entries per week</td></tr><tr><td><code>limits.weekly.days</code></td><td>list&lt;int&gt;</td><td><code>[]</code></td><td><code>1</code>–<code>7</code> (1 = Monday)</td><td>Allowed weekdays; empty list does not restrict; a bad entry fails dungeon loading</td></tr><tr><td><code>limits.monthly.count</code></td><td>int</td><td><code>0</code></td><td><code>&gt;= 0</code></td><td>Entries per month</td></tr><tr><td><code>limits.monthly.weeks</code></td><td>list&lt;int&gt;</td><td><code>[]</code></td><td><code>1</code>–<code>6</code></td><td>Allowed week-of-month (Monday-based); empty list does not restrict; a bad entry fails dungeon loading</td></tr><tr><td><code>limits.cooldown-seconds</code></td><td>int</td><td><code>0</code></td><td><code>&gt;= 0</code></td><td>Cooldown between entries; negatives become 0</td></tr></tbody></table><h3 id="world-and-difficulty" tabindex="-1"><code>world</code> and <code>difficulty</code> <a class="header-anchor" href="#world-and-difficulty" aria-label="Permalink to “world and difficulty”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>world.simulation-distance</code></td><td>int</td><td><code>6</code></td><td><code>—</code></td><td>Simulation distance applied per instance world</td></tr><tr><td><code>world.entity-limit</code></td><td>int</td><td><code>0</code></td><td><code>—</code></td><td>Entity cap per instance world; <code>0</code> means unlimited</td></tr><tr><td><code>difficulty.&lt;tier&gt;.mob-multiplier</code></td><td>double</td><td><code>1.0</code> (normal)</td><td><code>&gt;= 0</code></td><td>Mob stat multiplier; negatives clamp to 0</td></tr><tr><td><code>difficulty.&lt;tier&gt;.drop-multiplier</code></td><td>double</td><td><code>1.0</code> (normal)</td><td><code>&gt;= 0</code></td><td>Drop amount multiplier; negatives clamp to 0</td></tr><tr><td><code>difficulty.&lt;tier&gt;.respawn-count</code></td><td>int</td><td><code>3</code> (normal)</td><td><code>—</code></td><td>Remaining player respawns before spectating</td></tr></tbody></table><p>The template ships <code>normal</code> and <code>hard</code> tiers (<code>hard</code> uses <code>1.5</code> / <code>1.2</code> / <code>1</code>), and players pick one in the difficulty panel of the entry flow. Leave the <code>difficulty</code> section empty to keep the default two tiers, or add and remove tiers freely</p><h3 id="score-and-drop" tabindex="-1"><code>score</code> and <code>drop</code> <a class="header-anchor" href="#score-and-drop" aria-label="Permalink to “score and drop”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>score.damage-weight</code></td><td>double</td><td><code>1.0</code></td><td><code>—</code></td><td>Damage contribution weight</td></tr><tr><td><code>score.kill-weight</code></td><td>double</td><td><code>1.0</code></td><td><code>—</code></td><td>Kill contribution weight</td></tr><tr><td><code>score.heal-weight</code></td><td>double</td><td><code>1.0</code></td><td><code>—</code></td><td>Healing contribution weight</td></tr><tr><td><code>score.death-weight</code></td><td>double</td><td><code>1.0</code></td><td><code>—</code></td><td>Death contribution weight</td></tr><tr><td><code>score.defense-weight</code></td><td>double</td><td><code>1.0</code></td><td><code>—</code></td><td>Damage-taken / defense contribution weight</td></tr><tr><td><code>score.max</code></td><td>double</td><td><code>100.0</code></td><td>Falls back when <code>&lt;= 0</code></td><td>Score cap (completion time is not weighted yet); 0 or a negative value silently restores the default 100</td></tr><tr><td><code>drop.levels</code></td><td>map</td><td><code>common: 1</code>, <code>rare: 3</code>, <code>epic: 5</code></td><td>Integers, values below 1 become 1</td><td>Drop level weights, used by the score-based distribution mode</td></tr><tr><td><code>drop.default-mode</code></td><td>string</td><td><code>free</code></td><td>See <code>mode-allowed</code></td><td>Default drop distribution mode; an unknown mode falls back to <code>free</code></td></tr><tr><td><code>drop.mode-allowed</code></td><td>list&lt;string&gt;</td><td><code>[free, roll, killer, score, share]</code></td><td>Subset of the five modes</td><td>Modes offered to the leader in the distribution panel; invalid entries are dropped, and if all are invalid the default five are used</td></tr></tbody></table><p>The five modes: <code>free</code> vanilla drops for anyone to pick up, <code>roll</code> automatic rolling, <code>killer</code> to the killer, <code>score</code> weighted by run contribution, <code>share</code> split across the party; <code>drop.mode-allowed</code> decides which of them appear in the panel</p><h3 id="remaining-per-dungeon-keys" tabindex="-1">Remaining per-dungeon keys <a class="header-anchor" href="#remaining-per-dungeon-keys" aria-label="Permalink to “Remaining per-dungeon keys”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>commands.allow</code></td><td>list&lt;string&gt;</td><td><code>[]</code></td><td>Same syntax as global <code>commands.rules</code></td><td>Extra commands allowed in this dungeon; can override the regular guard, <strong>never the escape blacklist</strong></td></tr><tr><td><code>interaction.containers</code></td><td>boolean</td><td><code>true</code></td><td><code>true</code> / <code>false</code></td><td>Whether containers can be opened inside the dungeon</td></tr><tr><td><code>interaction.hoppers</code></td><td>boolean</td><td><code>false</code></td><td><code>true</code> / <code>false</code></td><td>Whether hoppers work; off by default</td></tr><tr><td><code>timer.messages</code></td><td>list&lt;int&gt;</td><td><code>[300, 60, 10]</code></td><td>Second marks</td><td>Countdown reminder marks pushing &quot;N seconds left&quot; to players</td></tr><tr><td><code>settlement.commands</code></td><td>list&lt;string&gt;</td><td><code>[]</code></td><td>Console command lines</td><td>Commands executed one by one on clear; <code>%player%</code> placeholder supported, handy for EmakiItem/EmakiLevel payouts</td></tr><tr><td><code>leaderboard.max-entries</code></td><td>int</td><td><code>100</code></td><td>Falls back when <code>&lt; 1</code></td><td>Leaderboard entries kept before evicting the worst; 0 or a negative value restores the default 100</td></tr></tbody></table><h2 id="reward-box-gui-gui-rewardbox-yml" tabindex="-1">Reward box GUI <code>gui/rewardbox.yml</code> <a class="header-anchor" href="#reward-box-gui-gui-rewardbox-yml" aria-label="Permalink to “Reward box GUI gui/rewardbox.yml”">​</a></h2><p>The layout of this GUI is fixed and not configurable; only two numbers are exposed:</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>default-pages</code></td><td>int</td><td><code>1</code></td><td><code>—</code></td><td>Base visible pages for players without a higher page permission</td></tr><tr><td><code>capacity-slots</code></td><td>int</td><td><code>135</code></td><td><code>—</code></td><td>Total reward box capacity in slots; reaching it means the box is full - see <a href="./challenges.html#reward-box-and-claiming">Challenges &amp; Rewards</a> for the full rules</td></tr></tbody></table><h2 id="flow-file-world-dungeonid-flow-yml" tabindex="-1">Flow file <code>world/&lt;dungeonId&gt;/flow.yml</code> <a class="header-anchor" href="#flow-file-world-dungeonid-flow-yml" aria-label="Permalink to “Flow file world/&lt;dungeonId&gt;/flow.yml”">​</a></h2><p>This file holds every flow module (rooms, waves, gates, options) and is generated when missing. See <a href="./flow.html">Flow &amp; Triggers</a> for the full structure</p>`,41)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};